package org.sleepwell.app;
import org.json.*;import java.util.*;import java.util.function.BooleanSupplier;
/** Public-documented v1 HTTPS pairing and a single dimmable light, no groups or discovery. */
final class HueBridgeApi implements AutoCloseable {
 static final class State{final boolean on;final int brightness;final String unchanged;State(boolean on,int brightness,String unchanged){this.on=on;this.brightness=brightness;this.unchanged=unchanged;}}
 static final class Light{final String id,name;Light(String id,String name){this.id=id;this.name=name;}}
 static final class Lights{final List<Light> lights;final int unsupported;Lights(List<Light> lights,int unsupported){this.lights=List.copyOf(lights);this.unsupported=unsupported;}}
 private final HueBridgeConfig config;private final HueBridgeClient client;
 HueBridgeApi(HueBridgeConfig config,BooleanSupplier alive){this.config=config;client=new HueBridgeClient(config,alive);}
 String pair()throws Exception{config.source();JSONArray result=new JSONArray(client.request("POST","/api",new JSONObject().put("devicetype","sleepwell#android")));if(result.length()!=1)throw new IllegalStateException("Pairing response is unsupported.");JSONObject row=result.getJSONObject(0);if(row.has("error")){JSONObject error=row.getJSONObject("error");long type=SoundEventBackup.whole(error,"type");throw new IllegalStateException(type==101?"Press the bridge link button, then explicitly retry Pair.":"The bridge rejected pairing. Check its official application settings.");}JSONObject success=row.getJSONObject("success");String key=success.getString("username");if(!key.matches("[A-Za-z0-9_-]{10,128}"))throw new IllegalStateException("Pairing credential format is unsupported.");return key;}
 Lights lights()throws Exception{config.paired();JSONObject rows=new JSONObject(client.request("GET","/api/"+config.key+"/lights",null));if(rows.length()>128)throw new IllegalStateException("This bridge has over 128 lights; this bounded integration is unsupported.");List<Light> found=new ArrayList<>();int unsupported=0;for(Iterator<String> ids=rows.keys();ids.hasNext();){String id=ids.next();if(!id.matches("[1-9][0-9]{0,5}")){unsupported++;continue;}JSONObject row=rows.getJSONObject(id);JSONObject state=row.optJSONObject("state");if(state==null||!state.has("bri")||Boolean.FALSE.equals(state.opt("reachable"))){unsupported++;continue;}parseState(row);Object raw=row.get("name");if(!(raw instanceof String name)||name.isBlank()||name.length()>100)throw new IllegalStateException("Bridge light names are unsupported.");found.add(new Light(id,name.replaceAll("[\\p{Cntrl}\\p{Cf}]"," ").strip()));}found.sort(Comparator.comparing((Light light)->light.name).thenComparing(light->light.id));return new Lights(found,unsupported);}
 State read()throws Exception{config.validate();return parseState(new JSONObject(client.request("GET","/api/"+config.key+"/lights/"+config.light,null)));}
 static State parseState(JSONObject row)throws Exception{JSONObject state=row.getJSONObject("state");Object on=state.get("on");long brightness=SoundEventBackup.whole(state,"bri");if(!(on instanceof Boolean)||brightness<1||brightness>254||state.has("reachable")&&(!(state.get("reachable") instanceof Boolean)||!state.getBoolean("reachable")))throw new IllegalStateException("The chosen light is unreachable or lacks supported brightness state.");JSONObject unchanged=new JSONObject();for(String key:List.of("hue","sat","xy","ct","colormode","effect","alert"))if(state.has(key))unchanged.put(key,state.get(key));return new State((Boolean)on,(int)brightness,unchanged.toString());}
 void set(boolean on,int brightness)throws Exception{config.validate();if(brightness<1||brightness>254)throw new IllegalArgumentException("Unsupported light level");JSONArray replies=new JSONArray(client.request("PUT","/api/"+config.key+"/lights/"+config.light+"/state",new JSONObject().put("on",on).put("bri",brightness)));if(replies.length()<1||replies.length()>4)throw new IllegalStateException("Light-control acknowledgement is unsupported.");boolean didOn=false,didBrightness=false;String prefix="/lights/"+config.light+"/state/";for(int n=0;n<replies.length();n++){JSONObject reply=replies.getJSONObject(n);if(reply.has("error"))throw new IllegalStateException("The bridge rejected a light-control command.");JSONObject success=reply.getJSONObject("success");for(Iterator<String> keys=success.keys();keys.hasNext();){String key=keys.next();if(key.equals(prefix+"on")){if(!(success.get(key) instanceof Boolean)||success.getBoolean(key)!=on)throw new IllegalStateException("Light on/off acknowledgement differs.");didOn=true;}else if(key.equals(prefix+"bri")){if(SoundEventBackup.whole(success,key)!=brightness)throw new IllegalStateException("Light brightness acknowledgement differs.");didBrightness=true;}else throw new IllegalStateException("The bridge acknowledged a different resource.");}}if(!didOn||!didBrightness)throw new IllegalStateException("Light-control acknowledgement is incomplete.");}
 @Override public void close(){client.close();}
}
